def sum_neighbors(grid):
    n_rows, n_cols = grid.shape
    output = np.full_like(grid, 0, dtype=int)
    for r in range(n_rows):
        for c in range(n_cols):
            if grid[r, c] == 5:
                continue
            total = 0
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n_rows and 0 <= nc < n_cols:
                        total += grid[nr, nc]
            output[r, c] = total % 10
    return output

output_neighbors_sum = sum_neighbors(grid)
